#include "Audio/AudioEngine.h"
#include "Audio/ChannelLayout.h"
#include "Session/Session.h"
#include <iostream>
#include <cmath>
namespace {
int checks=0;void expect(bool ok,const char* label){if(!ok)throw std::runtime_error(label);++checks;std::cout<<"PASS: "<<label<<'\n';}
std::shared_ptr<nova::Clip> asset(const juce::File& file,float level,bool impulse=false){auto clip=std::make_shared<nova::Clip>();clip->sampleRate=48000;clip->source=file;clip->samples.setSize(2,48000);clip->samples.clear();for(int c=0;c<2;++c)for(int n=0;n<48000;++n)clip->samples.setSample(c,n,impulse?(n==100?level:0):level);juce::WavAudioFormat format;std::unique_ptr<juce::AudioFormatWriter> writer(format.createWriterFor(file.createOutputStream().release(),48000,2,24,{},0));writer->writeFromAudioSampleBuffer(clip->samples,0,48000);return clip;}
juce::AudioBuffer<float> render(nova::AudioEngine& e,int n=512){juce::AudioBuffer<float> out(2,n);e.render(out.getArrayOfWritePointers(),2,n);return out;}
std::unique_ptr<nova::MixProcessor> delayed(const juce::PluginDescription& d,int latency){juce::String error;auto p=nova::MixProcessor::loadPlugin(d,48000,error);if(!p||!p->plugin)throw std::runtime_error(error.toStdString());p->setParameter(0,1);p->setParameter(1,float(latency)/2048);juce::AudioBuffer<float> warm(2,1);warm.clear();juce::MidiBuffer midi;p->plugin->processBlock(warm,midi);p->plugin->releaseResources();p->plugin->prepareToPlay(48000,256);p->prepare(48000);return p;}
}
int main(int argc,char** argv){juce::ScopedJuceInitialiser_GUI gui;try{expect(argc==3,"professional mixer fixture paths supplied");juce::File folder(juce::String::fromUTF8(argv[1]));folder.createDirectory();auto dir=folder.getChildFile(juce::Uuid().toString());dir.createDirectory();juce::String error;auto constant=asset(dir.getChildFile("constant.wav"),0.2f);
    nova::AudioEngine engine;engine.setOutputRate(48000);engine.setSmoothingTime(0);engine.addSharedClip(constant,error);engine.addSharedClip(constant,error);
    {nova::AudioEngine::MutationGuard guard(engine);engine.track(0).vcaGroup=0;engine.track(0).channelGroup=0;engine.vcaGroups[0].gain=0.5f;engine.channelGroups[0].gain=0.5f;}
    engine.play();auto out=render(engine);expect(std::abs(out.getSample(0,400)-0.25f)<1e-6f,"VCA and channel group gains multiply actual channel fader without altering other channel");
    engine.track(1).solo=true;out=render(engine);expect(std::abs(out.getSample(0,400)-0.2f)<1e-6f,"ordinary solo excludes unrelated grouped source");engine.track(0).soloSafe=true;out=render(engine);expect(std::abs(out.getSample(0,400)-0.25f)<1e-6f,"Solo Safe keeps channel audible during another channel solo");
    engine.channelGroups[0].mute=true;out=render(engine);expect(std::abs(out.getSample(0,400)-0.2f)<1e-6f,"group mute overrides Solo Safe");engine.channelGroups[0].mute=false;engine.track(0).soloSafe=false;engine.track(1).solo=false;engine.channelGroups[0].solo=true;out=render(engine);expect(std::abs(out.getSample(0,400)-0.05f)<1e-6f,"channel group solo includes its members");engine.channelGroups[0].solo=false;
    expect(engine.addAux("Send return",false,error)&&engine.setSend(0,0,2,true,error),"create advanced pre-fader send");engine.track(0).sends[0].gain=1;engine.track(0).sends[0].pan=1;engine.track(0).sends[0].width=0;out=render(engine);expect(std::abs(out.getSample(0,400)-0.25f)<1e-6f&&std::abs(out.getSample(1,400)-0.45f)<1e-6f,"send pan and mono width affect real pre-fader audio independently of VCA gain");engine.track(0).sends[0].mute=true;out=render(engine);expect(std::abs(out.getSample(1,400)-0.25f)<1e-6f,"advanced send mute silences only its return");
    const auto session=dir.getChildFile("groups.novadaw");expect(nova::Session::save(session,engine,error),"persist professional mixer settings");nova::AudioEngine loaded;loaded.setOutputRate(48000);expect(nova::Session::load(session,loaded,error)&&loaded.track(0).vcaGroup==0&&loaded.track(0).channelGroup==0&&loaded.vcaGroups[0].gain==0.5f&&loaded.track(0).sends[0].pan==1&&loaded.track(0).sends[0].mute,"groups memberships gain and advanced sends survive session load");
    juce::VST3PluginFormat format;juce::OwnedArray<juce::PluginDescription> descriptions;format.findAllTypesForFile(descriptions,juce::String::fromUTF8(argv[2]));expect(descriptions.size()==1,"discover real VST3 for sidechain latency path");nova::AudioEngine sc;sc.setOutputRate(48000);sc.setSmoothingTime(0);sc.addSharedClip(asset(dir.getChildFile("carrier.wav"),0.2f,true),error);sc.addSharedClip(asset(dir.getChildFile("key.wav"),0.7f,true),error);
    {nova::AudioEngine::MutationGuard guard(sc);sc.track(0).inserts[0]=delayed(*descriptions[0],17);sc.track(1).inserts[0]=delayed(*descriptions[0],31);auto gate=std::make_unique<nova::MixProcessor>(nova::EffectKind::gate);gate->setParameter(0,-40);gate->setParameter(1,0.1f);gate->setParameter(2,0);gate->setParameter(3,1);sc.track(0).inserts[1]=std::move(gate);sc.track(0).solo=true;sc.track(0).automationMode=nova::AutomationMode::read;sc.track(0).automation={{1,0,{{0,-40},{1,-40}}}};sc.prepareProcessors();}
    expect(sc.setSidechain(0,1,error)&&sc.latencySamples()==48,"sidechain dependency aligns main source and detector including preceding VST3 insert latency");
    sc.play();out=render(sc);const float gateGain=1-std::exp(-1.0f/(48000*0.0001f));expect(std::abs(out.getSample(1,148)-0.2f*gateGain)<1e-5f&&out.getMagnitude(1,0,148)<1e-6f,"external key opens actual gate at precisely aligned sample despite source being excluded by solo");
    expect(!sc.setSidechain(1,0,error)&&sc.track(1).sidechainSource==-1&&sc.latencySamples()==48,"sidechain feedback cycle rejected without replacing valid PDC plan");
    const auto scFile=dir.getChildFile("sidechain.novadaw");expect(nova::Session::save(scFile,sc,error)&&nova::Session::load(scFile,loaded,error)&&loaded.track(0).sidechainSource==1&&loaded.latencySamples()==48,"sidechain and PDC persist with opaque real VST3 state");
    nova::ChannelMatrix matrix;expect(matrix.configure({6},{2}),"prepare six-channel to stereo routing matrix");juce::AudioBuffer<float> surround(6,1),stereo(2,1);surround.clear();surround.setSample(2,0,1);surround.setSample(3,0,1);matrix.process(surround.getArrayOfReadPointers(),stereo.getArrayOfWritePointers(),1);expect(std::abs(stereo.getSample(0,0)-std::sqrt(0.5f))<1e-6f&&stereo.getSample(0,0)==stereo.getSample(1,0),"prepared surround matrix maps centre and excludes LFE from stereo downmix");expect(!matrix.configure({3},{2}),"unsupported layout rejected explicitly");
    std::cout<<checks<<" professional mixer checks passed\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
